( LC_ALL=C; . $HOME/hadavin-smoke/env.sh; KA=$(awk '$1=="A"{k=$2} END{print k}' $T/keys.txt); KB=$(awk '$1=="B"{k=$2} END{print k}' $T/keys.txt); if [ -z "$KA" ] || [ -z "$KB" ]; then echo "GATE2 key of A or B not in keys.txt: STOP"; elif [ "$KA" = "$KB" ]; then echo "GATE2 A and B have the same key: STOP"; else case "$KA$KB" in *[!A-Za-z0-9_-]*) echo "GATE2 key has an unexpected character: STOP";; *) N=$(pgq -U smk_count -d postgres -c "SELECT count(*) FROM mf_leads WHERE lead_key IN ('$KA','$KB')" | tee $T/gate2.out | head -n 1 | tr -d ' \r'); echo "GATE2 count: $N"; if [ "$N" = 2 ]; then echo "GATE2 PASS"; else echo "GATE2 FAIL: STOP"; fi;; esac; fi )
